// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "./ArbErrors.sol";

interface IAlgebraPool {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroToOne,
        int256 amountSpecified,
        uint160 limitSqrtPrice,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

library AlgebraSwapLib {
    using SafeERC20 for IERC20;

    struct AlgebraState {
        address expectedPool;
    }

    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    uint160 internal constant MAX_SQRT_RATIO =
        1461446703485210103287273052203988822378723970342;

    function swapExactInByPool(
        AlgebraState storage st,
        address pool,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        uint160 sqrtPriceLimitX96
    ) internal returns (uint256 amountOut, uint256 spent) {
        if (pool == address(0)) revert ArbErrors.POOL_ZERO();

        address t0 = IAlgebraPool(pool).token0();
        address t1 = IAlgebraPool(pool).token1();

        bool inIsT0 = (tokenIn == t0);
        bool inIsT1 = (tokenIn == t1);
        bool outIsT0 = (tokenOut == t0);
        bool outIsT1 = (tokenOut == t1);

        if (!((inIsT0 && outIsT1) || (inIsT1 && outIsT0))) revert ArbErrors.TOKEN_NOT_IN_POOL();

        bool zeroToOne = inIsT0;

        uint160 limit = sqrtPriceLimitX96;
        if (limit == 0) {
            limit = zeroToOne ? (MIN_SQRT_RATIO + 1) : (MAX_SQRT_RATIO - 1);
        }

        // guard
        st.expectedPool = pool;

        bytes memory data = abi.encode(pool, tokenIn, uint256(0), false);

        (int256 amount0, int256 amount1) = IAlgebraPool(pool).swap(
            address(this),
            zeroToOne,
            int256(amountIn),
            limit,
            data
        );

        st.expectedPool = address(0);

        // exactIn: input delta positive, output delta negative
        if (zeroToOne) {
            spent = uint256(amount0);
            amountOut = uint256(-amount1);
        } else {
            spent = uint256(amount1);
            amountOut = uint256(-amount0);
        }

        if (amountOut < amountOutMin) revert ArbErrors.SLIPPAGE();
    }

    /**
     * Вызывается из ArbExecutor.algebraSwapCallback(...)
     */
    function onSwapCallbackPay(
        AlgebraState storage st,
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) internal {
        if (st.expectedPool == address(0)) revert ArbErrors.NO_ACTIVE_ALGEBRA_SWAP();
        if (msg.sender != st.expectedPool) revert ArbErrors.UNEXPECTED_ALGEBRA_POOL();

        (address pool, address tokenIn, uint256 amountInMax, bool enforceMax) =
            abi.decode(data, (address, address, uint256, bool));

        // доп. защита
        if (pool != msg.sender) revert ArbErrors.UNEXPECTED_ALGEBRA_POOL();

        if (amount0Delta > 0) {
            address t0 = IAlgebraPool(pool).token0();
            if (tokenIn != t0) revert ArbErrors.TOKEN_NOT_IN_POOL();

            uint256 pay = uint256(amount0Delta);
            if (enforceMax && pay > amountInMax) revert ArbErrors.SLIPPAGE();

            IERC20(t0).safeTransfer(pool, pay);
            return;
        }

        if (amount1Delta > 0) {
            address t1 = IAlgebraPool(pool).token1();
            if (tokenIn != t1) revert ArbErrors.TOKEN_NOT_IN_POOL();

            uint256 pay = uint256(amount1Delta);
            if (enforceMax && pay > amountInMax) revert ArbErrors.SLIPPAGE();

            IERC20(t1).safeTransfer(pool, pay);
            return;
        }
    }
}

