// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Deployed at: 0x4ffDddC895719C3f662364e79f989C4deea44118

import "./ArbVault.sol";

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "./ArbErrors.sol";
import "./V2SwapLib.sol";
import "./V3SwapLib.sol";
import "./CamelotV2SwapLib.sol";
import "./AlgebraSwapLib.sol";

/* =========================================================
 * Interfaces (callback)
 * ========================================================= */

interface IUniswapV3SwapCallback {
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}

interface IAlgebraSwapCallback {
    function algebraSwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}

/* =========================================================
 * ArbExecutor
 * ========================================================= */

contract ArbExecutor is ArbVault, IUniswapV3SwapCallback, IAlgebraSwapCallback {
    using SafeERC20 for IERC20;

    uint256 public constant MAX_LOSS_BPS = 100; // 100 = 1%

    // ✅ V3 callback guard state (lives in ArbExecutor storage)
    V3SwapLib.V3State private _v3;

    // ✅ Algebra / Camelot V3 callback guard state
    AlgebraSwapLib.AlgebraState private _algebra;

    // =========================================================
    // Events (runtime analytics)
    // =========================================================

    event ArbExecuted(
        uint256 indexed blockNumber,
        uint256 blockTimestamp,
        address indexed profitToken,
        uint256 startBalance,
        uint256 endBalance,
        int256 profit,
        uint256 totalGasUsed,
        uint256 stepsCount,
        bool revertIfLoss
    );

    event SwapStepExecuted(
        uint256 indexed index,
        uint8 kind,              // uint8(SwapKind)
        address indexed target,  // router or pool
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 gasUsed
    );

    // =========================================================
    // Errors (contract-level)
    // =========================================================
    error Simulated(ArbSummary summary, SwapLog[] logs);

    error ArbExecutionLoss(ArbSummary summary, SwapLog[] logs);

    error LOSS_EXCEEDS_LIMIT(uint256 loss, uint256 maxAllowed);

    error NO_STEPS();
    error PROFIT_TOKEN_ZERO();
    error TOKEN_ZERO();

    error AMOUNT_IN_ZERO();

    error DEADLINE_EXPIRED();

    error UNKNOWN_SWAP_KIND();

    error ZERO_ADDRESS();

    // --- auto amountIn only for step #2 exact-in ---
    error SECOND_STEP_AMOUNTIN_ZERO_NOT_ALLOWED();
    error SECOND_STEP_PREV_TOKEN_MISMATCH();
    error SECOND_STEP_PREV_OUT_ZERO();
    // =========================================================
    // Types
    // =========================================================

    enum SwapKind {
        V2_EXACT_IN,
        V3_POOL_EXACT_IN,
        CAMELOT_V2_EXACT_IN,
        ALGEBRA_POOL_EXACT_IN,
        V4_POOL_EXACT_IN           // kind=4
    }

    struct SwapStep {
        SwapKind kind;

        // V2
        address router;
        address[] path;

        // V3
        address pool;

        // common
        address tokenIn;
        address tokenOut;

        // EXACT IN
        uint256 amountIn;        // if 0 and step index == 1 => use prev step amountOut
        uint256 amountOutMin;    // slippage guard (can be 0)

        // V3
        uint160 sqrtPriceLimitX96;

        uint256 deadline; // 0 => block.timestamp + DEFAULT_DEADLINE_SECONDS
    }

    struct SwapLog {
        uint256 index;

        SwapKind kind;
        address target;

        address tokenIn;
        address tokenOut;

        uint256 amountIn;   // фактически потрачено
        uint256 amountOut;  // фактически получено

        uint256 gasUsed;
    }

    struct ArbSummary {
        uint256 blockNumber;
        uint256 blockTimestamp;

        address profitToken;
        uint256 startBalance;
        uint256 endBalance;

        int256 profit;
        uint256 totalGasUsed;
        uint256 stepsCount;
    }

    // =========================================================
    // Allowlist (who can call simulateSwaps)
    // =========================================================

    error NOT_AUTHORIZED_CALLER(address caller);

    event AllowedCallerAdded(address indexed caller);
    event AllowedCallerRemoved(address indexed caller);

    mapping(address => bool) public isAllowedCaller;  // быстрый чек
    address[] private _allowedCallers;                // список для чтения

    modifier onlyOwnerOrAllowed() {
        if (msg.sender != owner() && !isAllowedCaller[msg.sender]) {
            revert NOT_AUTHORIZED_CALLER(msg.sender);
        }
        _;
    }

    function addAllowedCaller(address caller) external onlyOwner {
        if (caller == address(0)) revert ZERO_ADDRESS();
        if (isAllowedCaller[caller]) return;

        isAllowedCaller[caller] = true;
        _allowedCallers.push(caller);

        emit AllowedCallerAdded(caller);
    }

    function removeAllowedCaller(address caller) external onlyOwner {
        if (!isAllowedCaller[caller]) return;

        isAllowedCaller[caller] = false;

        // remove from array (swap & pop)
        uint256 len = _allowedCallers.length;
        for (uint256 i = 0; i < len; i++) {
            if (_allowedCallers[i] == caller) {
                if (i != len - 1) {
                    _allowedCallers[i] = _allowedCallers[len - 1];
                }
                _allowedCallers.pop();
                break;
            }
        }

        emit AllowedCallerRemoved(caller);
    }

    function getAllowedCallers() external view returns (address[] memory) {
        return _allowedCallers;
    }

    function allowedCallersCount() external view returns (uint256) {
        return _allowedCallers.length;
    }

    // =========================================================
    // Config
    // =========================================================

    uint256 public constant DEFAULT_DEADLINE_SECONDS = 120;

    constructor(address initialOwner) ArbVault(initialOwner) {}

    // =========================================================
    // Core
    // =========================================================

    function _executeSwapsCore(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss,
        bool emitEvents
    ) internal returns (ArbSummary memory summary, SwapLog[] memory logs) {
        if (steps.length == 0) revert NO_STEPS();
        if (profitToken == address(0)) revert PROFIT_TOKEN_ZERO();

        uint256 gasStartTotal = gasleft();

        uint256 startBal = _balanceOf(profitToken);
        logs = new SwapLog[](steps.length);

        uint256 prevOut = 0;
        address prevTokenOut = address(0);

        for (uint256 i = 0; i < steps.length; i++) {
            uint256 gasStartStep = gasleft();
            SwapStep calldata s = steps[i];

            if (s.tokenIn == address(0) || s.tokenOut == address(0)) revert TOKEN_ZERO();

            uint256 deadline = (s.deadline == 0)
                ? (block.timestamp + DEFAULT_DEADLINE_SECONDS)
                : s.deadline;
            if (block.timestamp > deadline) revert DEADLINE_EXPIRED();

            (uint256 amountOutActual, uint256 spentActual) =
                            _doSwapWithResolution(i, s, prevOut, prevTokenOut, deadline);

            uint256 gasUsedStep = gasStartStep - gasleft();
            address target = _targetOf(s);

            logs[i] = SwapLog({
                index: i,
                kind: s.kind,
                target: target,
                tokenIn: s.tokenIn,
                tokenOut: s.tokenOut,
                amountIn: spentActual,
                amountOut: amountOutActual,
                gasUsed: gasUsedStep
            });

            if (emitEvents) {
                emit SwapStepExecuted(
                    i,
                    uint8(s.kind),
                    target,
                    s.tokenIn,
                    s.tokenOut,
                    spentActual,
                    amountOutActual,
                    gasUsedStep
                );
            }

            prevOut = amountOutActual;
            prevTokenOut = s.tokenOut;
        }

        uint256 endBal = _balanceOf(profitToken);
        int256 profit = int256(endBal) - int256(startBal);
        uint256 totalGasUsed = gasStartTotal - gasleft();

        summary = ArbSummary({
            blockNumber: block.number,
            blockTimestamp: block.timestamp,
            profitToken: profitToken,
            startBalance: startBal,
            endBalance: endBal,
            profit: profit,
            totalGasUsed: totalGasUsed,
            stepsCount: steps.length
        });

        if (profit < 0) {
            if (revertIfLoss) {
                revert ArbExecutionLoss(summary, logs);
            }
            if (startBal == 0) revert LOSS_EXCEEDS_LIMIT(0, 0);

            uint256 loss = startBal - endBal;
            uint256 maxAllowedLoss = (startBal * MAX_LOSS_BPS) / 10_000;
            if (loss > maxAllowedLoss) revert LOSS_EXCEEDS_LIMIT(loss, maxAllowedLoss);
        }

        if (emitEvents) {
            emit ArbExecuted(
                block.number,
                block.timestamp,
                profitToken,
                startBal,
                endBal,
                profit,
                totalGasUsed,
                steps.length,
                revertIfLoss
            );
        }

        return (summary, logs);
    }

// --- Реальное исполнение (как было), просто теперь через core ---
    function executeSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss,
        bool emitEvents
    )
    external
    onlyOwner
    nonReentrant
    returns (ArbSummary memory summary, SwapLog[] memory logs)
    {
        return _executeSwapsCore(steps, profitToken, revertIfLoss, emitEvents);
    }

// --- СИМУЛЯЦИЯ: безопасна, потому что ВСЕГДА REVERT ---
// Можно сделать public/external без onlyOwner.
// nonReentrant тут не нужен (и лучше не ставить).
    function simulateSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss
    ) external onlyOwnerOrAllowed {
        (ArbSummary memory summary, SwapLog[] memory logs) =
                        _executeSwapsCore(steps, profitToken, revertIfLoss, false);

        revert Simulated(summary, logs);
    }

    function _targetOf(SwapStep calldata s) internal pure returns (address) {
        if (s.kind == SwapKind.V2_EXACT_IN || s.kind == SwapKind.CAMELOT_V2_EXACT_IN) return s.router;
        return s.pool;
    }

    // =========================================================
    // Swap resolution + handlers
    // =========================================================

    function _doSwapWithResolution(
        uint256 i,
        SwapStep calldata s,
        uint256 prevOut,
        address prevTokenOut,
        uint256 deadline
    ) internal returns (uint256 amountOutActual, uint256 spentActual) {
        // -------- EXACT IN kinds (allow auto amountIn on step #2) --------
        if (s.kind == SwapKind.V2_EXACT_IN
            || s.kind == SwapKind.V3_POOL_EXACT_IN
            || s.kind == SwapKind.CAMELOT_V2_EXACT_IN
            || s.kind == SwapKind.ALGEBRA_POOL_EXACT_IN
            || s.kind == SwapKind.V4_POOL_EXACT_IN
        ) {
            uint256 amountInResolved = s.amountIn;

            if (amountInResolved == 0) {
                if (i == 1) {
                    if (prevTokenOut != s.tokenIn) revert SECOND_STEP_PREV_TOKEN_MISMATCH();
                    if (prevOut == 0) revert SECOND_STEP_PREV_OUT_ZERO();
                    amountInResolved = prevOut;
                } else {
                    if (i == 0) revert AMOUNT_IN_ZERO();
                    revert SECOND_STEP_AMOUNTIN_ZERO_NOT_ALLOWED();
                }
            }
            if (amountInResolved == 0) revert AMOUNT_IN_ZERO();

            return _doSwapExactIn(s, amountInResolved, deadline);
        }

        revert UNKNOWN_SWAP_KIND();
    }

    function _doSwapExactIn(
        SwapStep calldata s,
        uint256 amountInResolved,
        uint256 deadline
    ) internal returns (uint256 amountOutActual, uint256 spentActual) {
        if (s.kind == SwapKind.V2_EXACT_IN) {
            (amountOutActual, spentActual) = V2SwapLib.swapExactIn(
                s.router,
                s.tokenIn,
                s.tokenOut,
                s.path,
                amountInResolved,
                s.amountOutMin,
                deadline
            );
            return (amountOutActual, spentActual);
        }

        if (s.kind == SwapKind.V3_POOL_EXACT_IN) {
            (amountOutActual, spentActual) = V3SwapLib.swapExactInByPool(
                _v3,
                s.pool,
                s.tokenIn,
                s.tokenOut,
                amountInResolved,
                s.amountOutMin,
                s.sqrtPriceLimitX96
            );
            return (amountOutActual, spentActual);
        }

        if (s.kind == SwapKind.CAMELOT_V2_EXACT_IN) {
            (amountOutActual, spentActual) = CamelotV2SwapLib.swapExactIn(
                s.router,
                s.tokenIn,
                s.tokenOut,
                s.path,
                amountInResolved,
                s.amountOutMin,
                deadline
            );
            return (amountOutActual, spentActual);
        }

        if (s.kind == SwapKind.ALGEBRA_POOL_EXACT_IN) {
            (amountOutActual, spentActual) = AlgebraSwapLib.swapExactInByPool(
                _algebra,
                s.pool,
                s.tokenIn,
                s.tokenOut,
                amountInResolved,
                s.amountOutMin,
                s.sqrtPriceLimitX96
            );
            return (amountOutActual, spentActual);
        }

        revert UNKNOWN_SWAP_KIND();
    }

    // =========================================================
    // V3 callback: pay pool (delegated to lib)
    // =========================================================

    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external override {
        V3SwapLib.onSwapCallbackPay(_v3, amount0Delta, amount1Delta, data);
    }

    // =========================================================
    // Algebra / Camelot V3 callback: pay pool (delegated to lib)
    // =========================================================

    function algebraSwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external override {
        AlgebraSwapLib.onSwapCallbackPay(_algebra, amount0Delta, amount1Delta, data);
    }

    // =========================================================
    // Utils
    // =========================================================

    function _balanceOf(address token) internal view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }
}

