// SPDX-License-Identifier: MIT

// Deployed at: 0xe76fF183A7d5895f9754C4265e527D8442A0Ae34
pragma solidity ^0.8.20;

import "./ArbVault.sol";

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/* =========================================================
 * Interfaces (top-level)
 * ========================================================= */

interface IUniswapV2RouterLike {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface IV3PoolLike {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,          // exactIn: positive, exactOut: negative
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

interface IUniswapV3SwapCallback {
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}

/* =========================================================
 * ArbExecutor
 * ========================================================= */

contract ArbExecutorOld is ArbVault, IUniswapV3SwapCallback {

    using SafeERC20 for IERC20;
    uint256 public constant MAX_LOSS_BPS = 100; // 100 = 1% (basis points)

    // --- V3 callback guard ---
    address private _expectedV3Pool;

    // =========================================================
    // Events (runtime analytics)
    // =========================================================

    event ArbExecuted(
        uint256 indexed blockNumber,
        uint256 blockTimestamp,
        address indexed profitToken,
        uint256 startBalance,
        uint256 endBalance,
        int256 profit,
        uint256 totalGasUsed,
        uint256 stepsCount,
        bool revertIfLoss
    );

    event SwapStepExecuted(
        uint256 indexed index,
        uint8 kind,              // uint8(SwapKind)
        address indexed target,  // router or pool
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut,
        uint256 gasUsed
    );

    error UNEXPECTED_V3_POOL();
    error NO_ACTIVE_V3_SWAP();

    // =========================================================
    // Errors
    // =========================================================

    error ArbExecutionLoss(ArbSummary summary, SwapLog[] logs);

    error LOSS_EXCEEDS_LIMIT(uint256 loss, uint256 maxAllowed);

    error NO_STEPS();
    error PROFIT_TOKEN_ZERO();
    error TOKEN_ZERO();

    error AMOUNT_IN_ZERO();
    error AMOUNT_OUT_ZERO();
    error AMOUNT_IN_MAX_ZERO();

    error DEADLINE_EXPIRED();

    error PATH_TOO_SHORT();
    error ROUTER_ZERO();
    error POOL_ZERO();
    error TOKEN_NOT_IN_POOL();
    error NOT_FROM_POOL();
    error SLIPPAGE();
    error UNKNOWN_SWAP_KIND();

    // --- auto amountIn only for step #2 exact-in ---
    error SECOND_STEP_AMOUNTIN_ZERO_NOT_ALLOWED();
    error SECOND_STEP_PREV_TOKEN_MISMATCH();
    error SECOND_STEP_PREV_OUT_ZERO();

    // =========================================================
    // Types
    // =========================================================

    enum SwapKind {
        V2_EXACT_IN,
        V3_POOL_EXACT_IN
    }

    struct SwapStep {
        SwapKind kind;

        // V2
        address router;
        address[] path;

        // V3
        address pool;

        // common
        address tokenIn;
        address tokenOut;

        // EXACT IN
        uint256 amountIn;        // if 0 and step index == 1 and exact-in => use prev step amountOut
        uint256 amountOutMin;    // exact-in slippage guard (can be 0)

        // V3
        uint160 sqrtPriceLimitX96;

        uint256 deadline; // 0 => block.timestamp + DEFAULT_DEADLINE_SECONDS
    }

    struct SwapLog {
        uint256 index;

        SwapKind kind;
        address target;

        address tokenIn;
        address tokenOut;

        uint256 amountIn;   // фактически потрачено
        uint256 amountOut;  // фактически получено

        uint256 gasUsed;
    }

    struct ArbSummary {
        uint256 blockNumber;
        uint256 blockTimestamp;

        address profitToken;
        uint256 startBalance;
        uint256 endBalance;

        int256 profit;
        uint256 totalGasUsed;
        uint256 stepsCount;
    }

    // =========================================================
    // Config
    // =========================================================

    uint256 public constant DEFAULT_DEADLINE_SECONDS = 120;

    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    uint160 internal constant MAX_SQRT_RATIO =
    1461446703485210103287273052203988822378723970342;

    constructor(address initialOwner) ArbVault(initialOwner) {}

    // =========================================================
    // Core
    // =========================================================

    function executeSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss,
        bool emitEvents
    ) external onlyOwner nonReentrant returns (ArbSummary memory summary, SwapLog[] memory logs) {
        if (steps.length == 0) revert NO_STEPS();
        if (profitToken == address(0)) revert PROFIT_TOKEN_ZERO();

        uint256 gasStartTotal = gasleft();

        uint256 startBal = _balanceOf(profitToken);
        logs = new SwapLog[](steps.length);

        // Track previous step actual out + tokenOut
        uint256 prevOut = 0;
        address prevTokenOut = address(0);

        for (uint256 i = 0; i < steps.length; i++) {
            uint256 gasStartStep = gasleft();
            SwapStep calldata s = steps[i];

            if (s.tokenIn == address(0) || s.tokenOut == address(0)) revert TOKEN_ZERO();

            uint256 deadline = (s.deadline == 0)
                ? (block.timestamp + DEFAULT_DEADLINE_SECONDS)
                : s.deadline;
            if (block.timestamp > deadline) revert DEADLINE_EXPIRED();

            // execute
            (uint256 amountOutActual, uint256 spentActual) = _doSwapWithResolution(i, steps, s, prevOut, prevTokenOut, deadline);

            uint256 gasUsedStep = gasStartStep - gasleft();

            address target = _targetOf(s);

            logs[i] = SwapLog({
                index: i,
                kind: s.kind,
                target: target,
                tokenIn: s.tokenIn,
                tokenOut: s.tokenOut,
                amountIn: spentActual,
                amountOut: amountOutActual,
                gasUsed: gasUsedStep
            });

            if (emitEvents) {
                emit SwapStepExecuted(
                    i,
                    uint8(s.kind),
                    target,
                    s.tokenIn,
                    s.tokenOut,
                    spentActual,
                    amountOutActual,
                    gasUsedStep
                );
            }

            // update prev trackers
            prevOut = amountOutActual;
            prevTokenOut = s.tokenOut;
        }

        uint256 endBal = _balanceOf(profitToken);
        int256 profit = int256(endBal) - int256(startBal);

        uint256 totalGasUsed = gasStartTotal - gasleft();

        summary = ArbSummary({
            blockNumber: block.number,
            blockTimestamp: block.timestamp,
            profitToken: profitToken,
            startBalance: startBal,
            endBalance: endBal,
            profit: profit,
            totalGasUsed: totalGasUsed,
            stepsCount: steps.length
        });

        if (profit < 0) {
            if (revertIfLoss) {
                revert ArbExecutionLoss(summary, logs);
            }

            // revertIfLoss == false: allow small loss, but cap it
            if (startBal == 0) {
                // with 0 start balance, any "loss" doesn't make sense -> revert to be safe
                revert LOSS_EXCEEDS_LIMIT(0, 0);
            }

            uint256 loss = startBal - endBal; // safe because profit<0 => endBal < startBal
            uint256 maxAllowedLoss = (startBal * MAX_LOSS_BPS) / 10_000;

            if (loss > maxAllowedLoss) {
                revert LOSS_EXCEEDS_LIMIT(loss, maxAllowedLoss);
            }
        }

        if (emitEvents) {
            emit ArbExecuted(
                block.number,
                block.timestamp,
                profitToken,
                startBal,
                endBal,
                profit,
                totalGasUsed,
                steps.length,
                revertIfLoss
            );
        }

        return (summary, logs);
    }

    function _targetOf(SwapStep calldata s) internal pure returns (address) {
        if (s.kind == SwapKind.V2_EXACT_IN) return s.router;
        return s.pool;
    }

    // =========================================================
    // Swap handlers
    // =========================================================

    function _doSwapWithResolution(
        uint256 i,
        SwapStep[] calldata /*steps*/,
        SwapStep calldata s,
        uint256 prevOut,
        address prevTokenOut,
        uint256 deadline
    ) internal returns (uint256 amountOutActual, uint256 spentActual) {
        // -------- EXACT IN kinds (allow auto amountIn on step #2) --------
        if (s.kind == SwapKind.V2_EXACT_IN || s.kind == SwapKind.V3_POOL_EXACT_IN) {
            uint256 amountInResolved = s.amountIn;

            if (amountInResolved == 0) {
                if (i == 1) {
                    if (prevTokenOut != s.tokenIn) revert SECOND_STEP_PREV_TOKEN_MISMATCH();
                    if (prevOut == 0) revert SECOND_STEP_PREV_OUT_ZERO();
                    amountInResolved = prevOut;
                } else {
                    if (i == 0) revert AMOUNT_IN_ZERO();
                    revert SECOND_STEP_AMOUNTIN_ZERO_NOT_ALLOWED();
                }
            }
            if (amountInResolved == 0) revert AMOUNT_IN_ZERO();

            return _doSwapExactIn(s, amountInResolved, deadline);
        }

        revert UNKNOWN_SWAP_KIND();
    }

    function _doSwapExactIn(
        SwapStep calldata s,
        uint256 amountInResolved,
        uint256 deadline
    ) internal returns (uint256 amountOutActual, uint256 spentActual) {
        if (s.kind == SwapKind.V2_EXACT_IN) {
            if (s.router == address(0)) revert ROUTER_ZERO();

            address[] memory path = (s.path.length >= 2)
                ? s.path
                : _defaultPath(s.tokenIn, s.tokenOut);
            if (path.length < 2) revert PATH_TOO_SHORT();

            // ✅ safety: path must match tokens
            if (path[0] != s.tokenIn || path[path.length - 1] != s.tokenOut) revert TOKEN_NOT_IN_POOL();

            _ensureAllowance(s.tokenIn, s.router, amountInResolved);

            uint[] memory amounts = IUniswapV2RouterLike(s.router).swapExactTokensForTokens(
                amountInResolved,
                s.amountOutMin, // can be 0
                path,
                address(this),
                deadline
            );

            spentActual = amounts[0];
            amountOutActual = amounts[amounts.length - 1];
            return (amountOutActual, spentActual);
        }

        if (s.kind == SwapKind.V3_POOL_EXACT_IN) {
            if (s.pool == address(0)) revert POOL_ZERO();

            (amountOutActual, spentActual) = _v3SwapExactInByPool(
                s.pool,
                s.tokenIn,
                s.tokenOut,
                amountInResolved,
                s.amountOutMin,
                s.sqrtPriceLimitX96
            );
            return (amountOutActual, spentActual);
        }

        revert UNKNOWN_SWAP_KIND();
    }

    // =========================================================
    // V3 swaps
    // =========================================================

    function _v3SwapExactInByPool(
        address pool,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        uint160 sqrtPriceLimitX96
    ) internal returns (uint256 amountOut, uint256 spent) {
        address t0 = IV3PoolLike(pool).token0();
        address t1 = IV3PoolLike(pool).token1();

        bool inIsT0 = (tokenIn == t0);
        bool inIsT1 = (tokenIn == t1);
        bool outIsT0 = (tokenOut == t0);
        bool outIsT1 = (tokenOut == t1);

        if (!((inIsT0 && outIsT1) || (inIsT1 && outIsT0))) revert TOKEN_NOT_IN_POOL();

        bool zeroForOne = inIsT0;

        uint160 limit = sqrtPriceLimitX96;
        if (limit == 0) {
            limit = zeroForOne ? (MIN_SQRT_RATIO + 1) : (MAX_SQRT_RATIO - 1);
        }

        // ✅ set expected pool BEFORE calling swap
        _expectedV3Pool = pool;

        // data: pool, tokenIn, amountInMax(0), enforceMax(false)
        bytes memory data = abi.encode(pool, tokenIn, uint256(0), false);

        (int256 amount0, int256 amount1) = IV3PoolLike(pool).swap(
            address(this),
            zeroForOne,
            int256(amountIn), // exact input
            limit,
            data
        );

        _expectedV3Pool = address(0);

        // ✅ correct delta handling:
        // exactIn: input delta positive, output delta negative
        if (zeroForOne) {
            // token0 in (amount0 > 0), token1 out (amount1 < 0)
            spent = uint256(amount0);
            amountOut = uint256(-amount1);
        } else {
            // token1 in (amount1 > 0), token0 out (amount0 < 0)
            spent = uint256(amount1);
            amountOut = uint256(-amount0);
        }

        if (amountOut < amountOutMin) revert SLIPPAGE();
        return (amountOut, spent);
    }

    // =========================================================
    // V3 callback: pay pool
    // =========================================================

    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external override {
        // ✅ must be inside active swap
        if (_expectedV3Pool == address(0)) revert NO_ACTIVE_V3_SWAP();

        // ✅ caller must be exactly the pool we are swapping with
        if (msg.sender != _expectedV3Pool) revert UNEXPECTED_V3_POOL();

        (address pool, address tokenIn, uint256 amountInMax, bool enforceMax) =
                            abi.decode(data, (address, address, uint256, bool));

        // ✅ optional: enforce decoded pool equals msg.sender (доп. защита)
        if (pool != msg.sender) revert UNEXPECTED_V3_POOL();


        // amount{0,1}Delta > 0 => we owe that token to the pool
        if (amount0Delta > 0) {
            address t0 = IV3PoolLike(pool).token0();
            if (tokenIn != t0) revert TOKEN_NOT_IN_POOL();

            uint256 pay = uint256(amount0Delta);
            if (enforceMax && pay > amountInMax) revert SLIPPAGE();

            IERC20(t0).safeTransfer(pool, pay);
            return;
        }

        if (amount1Delta > 0) {
            address t1 = IV3PoolLike(pool).token1();
            if (tokenIn != t1) revert TOKEN_NOT_IN_POOL();

            uint256 pay = uint256(amount1Delta);
            if (enforceMax && pay > amountInMax) revert SLIPPAGE();

            IERC20(t1).safeTransfer(pool, pay);
            return;
        }

        // nothing owed
    }

    // =========================================================
    // Utils
    // =========================================================

    function _defaultPath(address tokenIn, address tokenOut)
    internal
    pure
    returns (address[] memory path)
    {
        path = new address[](2);
        path[0] = tokenIn;
        path[1] = tokenOut;
    }

    function _balanceOf(address token) internal view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    function _ensureAllowance(address token, address spender, uint256 needed) internal {
        IERC20 erc = IERC20(token);
        uint256 allowance = erc.allowance(address(this), spender);
        if (allowance < needed) {
            erc.forceApprove(spender, type(uint256).max);
        }
    }
}

