// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Deployed at: 0xb8C793ea9201b0875BEc927585Ca101D8A142E7F

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "./ArbQuoterConfigLib.sol";

/* =========================================================
 * External DEX interfaces — quoting only
 * ========================================================= */

/// @dev Uniswap V2 / SushiSwap V2 / Camelot V2 routers all expose this.
interface IUniswapV2RouterQuote {
    function getAmountsOut(
        uint256 amountIn,
        address[] calldata path
    ) external view returns (uint256[] memory amounts);

    function getAmountsIn(
        uint256 amountOut,
        address[] calldata path
    ) external view returns (uint256[] memory amounts);
}

/// @dev Uniswap V3 / Sushi V3 pool — direct swap simulation for quoting.
///      Same signature as Algebra pools.
interface IV3PoolQuote {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

/// @dev Algebra (Camelot V3) pool — same swap signature, different callback name.
interface IAlgebraPoolQuote {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroToOne,
        int256 amountSpecified,
        uint160 limitSqrtPrice,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

/// @dev Uniswap V4 Quoter — deployed on Arbitrum at 0x3972C00f7Ed4885e145823eb7c655375D6f1e2a4
interface IUniswapV4Quoter {
    struct PoolKey {
        address currency0;
        address currency1;
        uint24  fee;
        int24   tickSpacing;
        address hooks;
    }

    struct QuoteExactSingleParams {
        PoolKey poolKey;
        bool    zeroForOne;
        uint128 exactAmount;
        bytes   hookData;
    }

    function quoteExactInputSingle(
        QuoteExactSingleParams memory params
    ) external returns (uint256 amountOut, uint256 gasEstimate);

    function quoteExactOutputSingle(
        QuoteExactSingleParams memory params
    ) external returns (uint256 amountIn, uint256 gasEstimate);
}

/* =========================================================
 * ArbQuoter — read-only quoting via DEX Router / direct pool simulation
 *
 * V2 / CamelotV2 (kind=0,2): router.getAmountsOut
 * V3            (kind=1):     direct pool.swap + uniswapV3SwapCallback revert
 * Algebra       (kind=3):     direct pool.swap + algebraSwapCallback revert
 * ========================================================= */
contract ArbQuoter is Ownable {

    // =========================================================
    // State
    // =========================================================

    address public v4Quoter;  // Uniswap V4 Quoter address

    // =========================================================
    // Errors
    // =========================================================

    error ZERO_ADDRESS();
    error UNKNOWN_KIND(uint8 kind);
    error NO_STEPS();
    error BAD_DECIMALS(uint8 decimals);

    /// @dev Thrown inside swap callbacks to carry the quote result back via revert.
    ///      For ExactIn:  amountIn = input spent, amountOut = output received
    ///      For ExactOut: amountIn = input required, amountOut = exact output requested
    error QuoteCallbackResult(uint256 amountIn, uint256 amountOut);

    // =========================================================
    // Constants — Algebra sqrt price limits (same as AlgebraSwapLib)
    // =========================================================

    uint160 private constant ALG_MIN_SQRT_RATIO = 4295128739;
    uint160 private constant ALG_MAX_SQRT_RATIO =
        1461446703485210103287273052203988822378723970342;

    // =========================================================
    // Structs — results
    // =========================================================

    struct QuoteResult {
        uint256 index;
        uint256 amountOut;
        bool    success;
    }

    struct QuoteBatchResult {
        QuoteResult[] quotes;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    /// @dev Price impact result for ExactIn quotes.
    /// - amountOut: output for amountIn
    /// - referenceAmountOut: output for referenceAmountIn (usually 100x smaller)
    /// - outPerInX18/referenceOutPerInX18: normalized prices in tokenOut per tokenIn, scaled by 1e18
    /// - priceImpactPpm: price impact in ppm (1e6 = 100%)
    /// - sellAmountOut: reverse ExactOut cost in tokenOut to buy back amountIn tokenIn
    /// - profit: int256(amountOut) - int256(sellAmountOut), both in tokenOut
    struct ImpactQuoteResult {
        uint256 amountOut;
        uint256 referenceAmountOut;
        uint256 outPerInX18;
        uint256 referenceOutPerInX18;
        uint256 priceImpactPpm;
        uint256 sellAmountOut;
        int256  profit;
        bool canTradeAmountIn; // true if target amountIn quote succeeded and produced non-zero output
        bool success;
    }

    struct ImpactQuoteBatchItem {
        uint256 index;
        uint256 amountOut;
        uint256 referenceAmountOut;
        uint256 outPerInX18;
        uint256 referenceOutPerInX18;
        uint256 priceImpactPpm;
        uint256 sellAmountOut;
        int256  profit;
        bool canTradeAmountIn;
        bool success;
    }

    struct ImpactQuoteBatchResult {
        ImpactQuoteBatchItem[] quotes;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    struct ConfigImpactQuoteItem {
        uint256 index;
        address pool;
        uint8   kind;
        ImpactQuoteResult buy;   // amountIn tokenIn -> tokenOut
        ImpactQuoteResult sell;  // amountOut tokenOut -> tokenIn, only when sellEnabled
        uint256 buyAmountOutHumanX18;  // buy.amountOut normalized by tokenOut decimals, scaled by 1e18
        uint256 sellAmountOutHumanX18; // sell.amountOut normalized by tokenIn decimals, scaled by 1e18
        uint256 buyPriceOutPerInX18;  // human-normalized tokenOut per tokenIn, scaled by 1e18
        uint256 sellPriceOutPerInX18; // human-normalized tokenOut per tokenIn from reverse sell quote, scaled by 1e18
        bool sellEnabled;
        bool success;
    }

    struct ConfigImpactQuoteBatchResult {
        ConfigImpactQuoteItem[] quotes;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    struct RoundTripResult {
        uint256 index;
        uint256 buyAmountOut;   // ExactIn:  amountIn tokenIn → buyAmountOut tokenOut
        uint256 sellAmountOut;  // ExactOut: sellAmountOut tokenOut → amountIn tokenIn (how much tokenOut needed to get amountIn back)
        int256  profit;         // int256(buyAmountOut) - int256(sellAmountOut), both in tokenOut. Positive = profitable.
        bool    success;
    }

    struct RoundTripBatchResult {
        RoundTripResult[] trips;
        uint256 blockNumber;
        uint256 gasUsed;
    }

