    // =========================================================
    // Swap callbacks — always revert with the quote result
    // =========================================================

    /// @dev Called by Uniswap V3 / Sushi V3 pools during swap simulation.
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external pure {
        _revertWithQuote(amount0Delta, amount1Delta, data);
    }

    /// @dev Called by Algebra (Camelot V3) pools during swap simulation.
    function algebraSwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external pure {
        _revertWithQuote(amount0Delta, amount1Delta, data);
    }

    /// @dev Shared callback logic: decode direction, extract amounts, revert.
    ///      For zeroForOne: token0 is input, token1 is output.
    ///      Positive delta = amount to pay (input), negative delta = amount received (output).
    function _revertWithQuote(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata /* data */
    ) internal pure {
        // amountIn  = the positive delta (what pool asks us to pay)
        // amountOut = the abs of negative delta (what pool gives us)
        uint256 amtIn;
        uint256 amtOut;

        if (amount0Delta > 0) {
            amtIn  = uint256(amount0Delta);
            amtOut = amount1Delta < 0 ? uint256(-amount1Delta) : 0;
        } else {
            amtIn  = amount1Delta > 0 ? uint256(amount1Delta) : 0;
            amtOut = uint256(-amount0Delta);
        }

        revert QuoteCallbackResult(amtIn, amtOut);
    }

