    /// @notice Quote all steps with price impact directly (calldata).
    function quoteExactInBatchWithImpact(
        ArbQuoterConfigLib.SwapStep[] calldata steps,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) external returns (ImpactQuoteBatchResult memory) {
        uint256 gasStart = gasleft();
        ImpactQuoteBatchResult memory result;
        result.quotes = _quoteExactInBatchWithImpactCalldata(steps, amountIn, referenceAmountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
        return result;
    }

    /// @notice Quote config-like input in one call: buy ExactIn impact and optional reverse sell ExactIn impact.
    function quoteConfigExactInWithImpact(
        ArbQuoterConfigLib.ConfigQuoteInput calldata cfg
    ) external returns (ConfigImpactQuoteBatchResult memory) {
        uint256 gasStart = gasleft();
        uint256 n = cfg.pairs.length;
        if (n == 0) revert NO_STEPS();

        ConfigImpactQuoteBatchResult memory result;

        bool sellEnabled = cfg.hasAmountOut && cfg.amountOut > 0;
        uint256 referenceAmountIn = _referenceOrDefault(cfg.amountIn, cfg.referenceAmountIn);
        uint256 referenceAmountOut = _referenceOrDefault(cfg.amountOut, cfg.referenceAmountOut);

        result.quotes = new ConfigImpactQuoteItem[](n);
        for (uint256 i = 0; i < n; i++) {
            ArbQuoterConfigLib.ConfigPairInput calldata pair = cfg.pairs[i];
            ArbQuoterConfigLib.SwapStep memory buyStep = ArbQuoterConfigLib.toStep(cfg, pair, false);
            ImpactQuoteResult memory buy = _quoteExactInWithImpact(buyStep, cfg.amountIn, referenceAmountIn);

            ImpactQuoteResult memory sell;
            if (sellEnabled) {
                ArbQuoterConfigLib.SwapStep memory sellStep = ArbQuoterConfigLib.toStep(cfg, pair, true);
                sell = _quoteExactInWithImpact(sellStep, cfg.amountOut, referenceAmountOut);
            }

            uint256 buyPriceOutPerInX18 = buy.success
                ? _priceOutPerInX18(buy.amountOut, cfg.amountIn, cfg.tokenInDecimals, cfg.tokenOutDecimals)
                : 0;
            uint256 sellPriceOutPerInX18 = (sellEnabled && sell.success)
                ? _priceOutPerInX18(cfg.amountOut, sell.amountOut, cfg.tokenInDecimals, cfg.tokenOutDecimals)
                : 0;
            uint256 buyAmountOutHumanX18 = buy.success
                ? _amountHumanX18(buy.amountOut, cfg.tokenOutDecimals)
                : 0;
            uint256 sellAmountOutHumanX18 = (sellEnabled && sell.success)
                ? _amountHumanX18(sell.amountOut, cfg.tokenInDecimals)
                : 0;

            result.quotes[i] = ConfigImpactQuoteItem({
                index: i,
                pool: pair.pool,
                kind: pair.kind,
                buy: buy,
                sell: sell,
                buyAmountOutHumanX18: buyAmountOutHumanX18,
                sellAmountOutHumanX18: sellAmountOutHumanX18,
                buyPriceOutPerInX18: buyPriceOutPerInX18,
                sellPriceOutPerInX18: sellPriceOutPerInX18,
                sellEnabled: sellEnabled,
                success: buy.success && (!sellEnabled || sell.success)
            });
        }

        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
        return result;
    }

