    // =========================================================
    // Internal — V4 quoting (via external Uniswap V4 Quoter)
    // =========================================================

    error V4_QUOTER_NOT_SET();

    /// @dev Build a V4 PoolKey from SwapStep V4 fields.
    ///      currency0 must be < currency1 (sorted order).
    function _buildV4PoolKey(
        ArbQuoterConfigLib.SwapStep memory step
    ) internal pure returns (IUniswapV4Quoter.PoolKey memory key) {
        address c0;
        address c1;
        if (step.tokenIn < step.tokenOut) {
            c0 = step.tokenIn;
            c1 = step.tokenOut;
        } else {
            c0 = step.tokenOut;
            c1 = step.tokenIn;
        }
        key = IUniswapV4Quoter.PoolKey({
            currency0:   c0,
            currency1:   c1,
            fee:         step.v4Fee,
            tickSpacing: step.v4TickSpacing,
            hooks:       step.v4Hooks
        });
    }

    /// @dev Quote V4 ExactIn via external Uniswap V4 Quoter.
    function _quoteV4ExactIn(
        ArbQuoterConfigLib.SwapStep memory step,
        uint256 amountIn
    ) internal returns (uint256 amountOut) {
        if (v4Quoter == address(0)) revert V4_QUOTER_NOT_SET();

        IUniswapV4Quoter.PoolKey memory poolKey = _buildV4PoolKey(step);
        bool zeroForOne = (step.tokenIn < step.tokenOut);

        IUniswapV4Quoter.QuoteExactSingleParams memory params =
            IUniswapV4Quoter.QuoteExactSingleParams({
                poolKey:    poolKey,
                zeroForOne: zeroForOne,
                exactAmount: uint128(amountIn),
                hookData:   ""
            });

        (amountOut,) = IUniswapV4Quoter(v4Quoter).quoteExactInputSingle(params);
    }

    /// @dev Quote V4 ExactOut via external Uniswap V4 Quoter.
    function _quoteV4ExactOut(
        ArbQuoterConfigLib.SwapStep memory step,
        uint256 amountOut
    ) internal returns (uint256 amountIn) {
        if (v4Quoter == address(0)) revert V4_QUOTER_NOT_SET();

        // For ExactOut, we invert: we want to know how much tokenIn to pay to get amountOut tokenOut
        IUniswapV4Quoter.PoolKey memory poolKey = _buildV4PoolKey(step);
        bool zeroForOne = (step.tokenIn < step.tokenOut);

        IUniswapV4Quoter.QuoteExactSingleParams memory params =
            IUniswapV4Quoter.QuoteExactSingleParams({
                poolKey:    poolKey,
                zeroForOne: zeroForOne,
                exactAmount: uint128(amountOut),
                hookData:   ""
            });

        (amountIn,) = IUniswapV4Quoter(v4Quoter).quoteExactOutputSingle(params);
    }

    /// @dev Decode QuoteCallbackResult(uint256, uint256) from revert data.
    function _decodeQuoteRevert(
        bytes memory reason
    ) internal pure returns (uint256 amtIn, uint256 amtOut) {
        bytes4 expected = QuoteCallbackResult.selector;
        if (reason.length >= 68) {
            bytes4 sel;
            assembly { sel := mload(add(reason, 32)) }
            if (sel == expected) {
                assembly {
                    amtIn  := mload(add(reason, 36))
                    amtOut := mload(add(reason, 68))
                }
                return (amtIn, amtOut);
            }
        }
        // Unknown revert — propagate
        assembly { revert(add(reason, 32), mload(reason)) }
    }

    function _referenceOrDefault(
        uint256 amount,
        uint256 referenceAmount
    ) internal pure returns (uint256) {
        if (referenceAmount != 0) return referenceAmount;
        if (amount == 0) return 0;

        uint256 computed = amount / 100;
        return computed == 0 ? 1 : computed;
    }

    function _priceOutPerInX18(
        uint256 amountOutRaw,
        uint256 amountInRaw,
        uint8 tokenInDecimals,
        uint8 tokenOutDecimals
    ) internal pure returns (uint256) {
        if (amountOutRaw == 0 || amountInRaw == 0) return 0;
        if (tokenInDecimals > 36) revert BAD_DECIMALS(tokenInDecimals);
        if (tokenOutDecimals > 36) revert BAD_DECIMALS(tokenOutDecimals);

        // Human price tokenOut/tokenIn scaled by 1e18:
        // (amountOutRaw / 10^outDec) / (amountInRaw / 10^inDec) * 1e18
        // = amountOutRaw * 10^inDec * 1e18 / (amountInRaw * 10^outDec)
        uint256 numeratorScale = (10 ** uint256(tokenInDecimals)) * 1e18;
        uint256 denominator = amountInRaw * (10 ** uint256(tokenOutDecimals));
        return Math.mulDiv(amountOutRaw, numeratorScale, denominator);
    }

    function _amountHumanX18(
        uint256 amountRaw,
        uint8 tokenDecimals
    ) internal pure returns (uint256) {
        if (amountRaw == 0) return 0;
        if (tokenDecimals > 36) revert BAD_DECIMALS(tokenDecimals);

        // Human amount scaled by 1e18:
        // (amountRaw / 10^tokenDecimals) * 1e18
        return Math.mulDiv(amountRaw, 1e18, 10 ** uint256(tokenDecimals));
    }

    /// @dev Safe wrapper: returns (amountOut, success). Does not revert on failure.
    function _quoteExactInSafe(
        ArbQuoterConfigLib.SwapStep memory step,
        uint256 amountIn
    ) internal returns (uint256 amountOut, bool success) {
        try this._quoteExactInExternal(step, amountIn) returns (uint256 out) {
            return (out, true);
        } catch {
            return (0, false);
        }
    }

    /// @dev Quote target/reference sizes and derive price impact.
    ///      priceImpactPpm = ((pRef - pTarget) / pRef) * 1e6, where p = outPerIn.
    function _quoteExactInWithImpact(
        ArbQuoterConfigLib.SwapStep memory step,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) internal returns (ImpactQuoteResult memory r) {
        if (amountIn == 0 || referenceAmountIn == 0) {
            r.success = false;
            return r;
        }

        (uint256 outTarget, bool okTarget) = _quoteExactInSafe(step, amountIn);
        (uint256 outRef, bool okRef) = _quoteExactInSafe(step, referenceAmountIn);

        r.amountOut = outTarget;
        r.referenceAmountOut = outRef;
        r.canTradeAmountIn = okTarget && outTarget > 0;

        if (r.canTradeAmountIn) {
            ArbQuoterConfigLib.SwapStep memory inv = ArbQuoterConfigLib.invertStep(step);
            (uint256 sellCost, bool sellOk) = _quoteExactOutSafe(inv, amountIn);
            if (sellOk) {
                r.sellAmountOut = sellCost;
                r.profit = outTarget >= sellCost
                    ? int256(outTarget - sellCost)
                    : -int256(sellCost - outTarget);
            }
        }

        if (!okTarget || !okRef || outTarget == 0 || outRef == 0) {
            r.success = false;
            return r;
        }

        uint256 pTargetX18 = (outTarget * 1e18) / amountIn;
        uint256 pRefX18 = (outRef * 1e18) / referenceAmountIn;

        r.outPerInX18 = pTargetX18;
        r.referenceOutPerInX18 = pRefX18;

        if (pRefX18 == 0 || pTargetX18 >= pRefX18) {
            r.priceImpactPpm = 0;
        } else {
            r.priceImpactPpm = ((pRefX18 - pTargetX18) * 1_000_000) / pRefX18;
        }

        r.success = true;
    }

    /// @dev External wrapper needed for try/catch on internal memory-param function.
    ///      Must only be called by this contract itself.
    function _quoteExactInExternal(
        ArbQuoterConfigLib.SwapStep calldata step,
        uint256 amountIn
    ) external returns (uint256) {
        require(msg.sender == address(this), "SELF_ONLY");
        return _quoteExactIn(step, amountIn);
    }

    // =========================================================
    // Internal — ExactOut quoting
    // =========================================================

    /// @dev Quote ExactOut: how much tokenIn is needed to receive exactly amountOut tokenOut.
    function _quoteExactOut(
        ArbQuoterConfigLib.SwapStep memory step,
        uint256 amountOut
    ) internal returns (uint256 amountIn) {
        uint8 kind = step.kind;

        // V2 / Camelot V2: router.getAmountsIn
        if (kind == 0 || kind == 2) {
            address[] memory path = step.path;
            if (path.length < 2) {
                path = new address[](2);
                path[0] = step.tokenIn;
                path[1] = step.tokenOut;
            }
            uint256[] memory amounts = IUniswapV2RouterQuote(step.router)
                .getAmountsIn(amountOut, path);
            return amounts[0];
        }

        // V3: ExactOut via pool.swap with negative amountSpecified
        if (kind == 1) {
            return _quoteV3ExactOut(step.pool, step.tokenIn, amountOut);
        }

        // Algebra: ExactOut via pool.swap with negative amountSpecified
        if (kind == 3) {
            return _quoteAlgebraExactOut(step.pool, step.tokenIn, amountOut);
        }

        // V4: ExactOut via external Uniswap V4 Quoter
        if (kind == 4) {
            return _quoteV4ExactOut(step, amountOut);
        }

        revert UNKNOWN_KIND(kind);
    }

    /// @dev Safe wrapper for ExactOut.
    function _quoteExactOutSafe(
        ArbQuoterConfigLib.SwapStep memory step,
        uint256 amountOut
    ) internal returns (uint256 amountIn, bool success) {
        try this._quoteExactOutExternal(step, amountOut) returns (uint256 inp) {
            return (inp, true);
        } catch {
            return (0, false);
        }
    }

    /// @dev External wrapper for ExactOut try/catch.
    function _quoteExactOutExternal(
        ArbQuoterConfigLib.SwapStep calldata step,
        uint256 amountOut
    ) external returns (uint256) {
        require(msg.sender == address(this), "SELF_ONLY");
        return _quoteExactOut(step, amountOut);
    }

    // =========================================================
    // Internal — batch helpers
    // =========================================================

    /// @dev Batch from calldata array.
    function _quoteExactInBatchInternal(
        ArbQuoterConfigLib.SwapStep[] calldata steps,
        uint256 amountIn
    ) internal returns (QuoteResult[] memory results) {
        uint256 n = steps.length;
        results = new QuoteResult[](n);
        for (uint256 i = 0; i < n; i++) {
            (uint256 out, bool ok) = _quoteExactInSafe(steps[i], amountIn);
            results[i] = QuoteResult({ index: i, amountOut: out, success: ok });
        }
    }

    /// @dev Batch from memory array (for store-based calls).
    function _quoteExactInBatchMem(
        ArbQuoterConfigLib.SwapStep[] memory steps,
        uint256 amountIn
    ) internal returns (QuoteResult[] memory results) {
        uint256 n = steps.length;
        results = new QuoteResult[](n);
        for (uint256 i = 0; i < n; i++) {
            (uint256 out, bool ok) = _quoteExactInSafe(steps[i], amountIn);
            results[i] = QuoteResult({ index: i, amountOut: out, success: ok });
        }
    }

    /// @dev Batch with impact from calldata.
    function _quoteExactInBatchWithImpactCalldata(
        ArbQuoterConfigLib.SwapStep[] calldata steps,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) internal returns (ImpactQuoteBatchItem[] memory results) {
        uint256 n = steps.length;
        results = new ImpactQuoteBatchItem[](n);
        for (uint256 i = 0; i < n; i++) {
            ImpactQuoteResult memory r = _quoteExactInWithImpact(steps[i], amountIn, referenceAmountIn);
            results[i] = ImpactQuoteBatchItem({
                index: i,
                amountOut: r.amountOut,
                referenceAmountOut: r.referenceAmountOut,
                outPerInX18: r.outPerInX18,
                referenceOutPerInX18: r.referenceOutPerInX18,
                priceImpactPpm: r.priceImpactPpm,
                sellAmountOut: r.sellAmountOut,
                profit: r.profit,
                canTradeAmountIn: r.canTradeAmountIn,
                success: r.success
            });
        }
    }

    /// @dev Batch with impact from memory array (store-based).
    function _quoteExactInBatchWithImpactMem(
        ArbQuoterConfigLib.SwapStep[] memory steps,
        uint256 amountIn,
        uint256 referenceAmountIn
    ) internal returns (ImpactQuoteBatchItem[] memory results) {
        uint256 n = steps.length;
        results = new ImpactQuoteBatchItem[](n);
        for (uint256 i = 0; i < n; i++) {
            ImpactQuoteResult memory r = _quoteExactInWithImpact(steps[i], amountIn, referenceAmountIn);
            results[i] = ImpactQuoteBatchItem({
                index: i,
                amountOut: r.amountOut,
                referenceAmountOut: r.referenceAmountOut,
                outPerInX18: r.outPerInX18,
                referenceOutPerInX18: r.referenceOutPerInX18,
                priceImpactPpm: r.priceImpactPpm,
                sellAmountOut: r.sellAmountOut,
                profit: r.profit,
                canTradeAmountIn: r.canTradeAmountIn,
                success: r.success
            });
        }
    }

    // =========================================================
    // Internal — round-trip helpers
    // =========================================================

    /// @dev Round-trip for a single step:
    ///      1) ExactIn:  amountIn tokenIn → buyAmountOut tokenOut
    ///      2) ExactOut:  sellAmountOut tokenOut → amountIn tokenIn  (how much tokenOut needed to buy back amountIn)
    ///      profit = buyAmountOut - sellAmountOut (both in tokenOut)
    ///      If profit > 0 → we got more tokenOut than needed to buy back our tokenIn.
    function _quoteRoundTripInternal(
        ArbQuoterConfigLib.SwapStep memory step,
        uint256 amountIn,
        uint256 index
    ) internal returns (RoundTripResult memory r) {
        r.index = index;

        // Step 1: ExactIn forward — amountIn tokenIn → buyAmountOut tokenOut
        (uint256 buyOut, bool buyOk) = _quoteExactInSafe(step, amountIn);
        if (!buyOk || buyOut == 0) {
            r.success = false;
            return r;
        }
        r.buyAmountOut = buyOut;

        // Step 2: ExactOut reverse — how much tokenOut to pay to get exactly amountIn tokenIn back
        // We invert the step (tokenOut→tokenIn) and ask: how much tokenOut input for amountIn tokenIn output
        ArbQuoterConfigLib.SwapStep memory inv = ArbQuoterConfigLib.invertStep(step);
        (uint256 sellCost, bool sellOk) = _quoteExactOutSafe(inv, amountIn);
        if (!sellOk) {
            r.success = false;
            return r;
        }

        r.sellAmountOut = sellCost;
        r.profit = int256(buyOut) - int256(sellCost);
        r.success = true;
    }

    /// @dev Batch round-trip from calldata.
    function _quoteRoundTripBatchCalldata(
        ArbQuoterConfigLib.SwapStep[] calldata steps,
        uint256 amountIn
    ) internal returns (RoundTripResult[] memory results) {
        uint256 n = steps.length;
        results = new RoundTripResult[](n);
        for (uint256 i = 0; i < n; i++) {
            results[i] = _quoteRoundTripInternal(steps[i], amountIn, i);
        }
    }

    /// @dev Batch round-trip from memory (store-based).
    function _quoteRoundTripBatchMem(
        ArbQuoterConfigLib.SwapStep[] memory steps,
        uint256 amountIn
    ) internal returns (RoundTripResult[] memory results) {
        uint256 n = steps.length;
        results = new RoundTripResult[](n);
        for (uint256 i = 0; i < n; i++) {
            results[i] = _quoteRoundTripInternal(steps[i], amountIn, i);
        }
    }

}

