// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @dev Shared config/step structs and conversion helpers for ArbQuoter.
library ArbQuoterConfigLib {
    struct SwapStep {
        uint8 kind;

        // V2 / Camelot V2
        address router;
        address[] path;

        // V3 / Algebra / metadata pool address for V2 rows
        address pool;

        // common
        address tokenIn;
        address tokenOut;

        // V4 (Uniswap V4) — PoolKey components
        uint24  v4Fee;
        int24   v4TickSpacing;
        address v4Hooks;
    }

    /// @dev ABI-friendly pair config prepared from stabs config off-chain.
    /// kind: 0=V2, 1=V3, 2=CamelotV2, 3=Algebra/CamelotV3, 4=V4.
    struct ConfigPairInput {
        uint8 kind;
        address router;
        address pool;
        uint24  v4Fee;
        int24   v4TickSpacing;
        address v4Hooks;
    }

    /// @dev ABI-friendly representation of ArbitrumPoolsConfigListStabs for quoting.
    /// amountOut is optional via hasAmountOut; when absent, only buy ExactIn impact is quoted.
    struct ConfigQuoteInput {
        address tokenIn;
        address tokenOut;
        uint8 tokenInDecimals;
        uint8 tokenOutDecimals;
        uint256 amountIn;
        uint256 referenceAmountIn;
        bool hasAmountOut;
        uint256 amountOut;
        uint256 referenceAmountOut;
        ConfigPairInput[] pairs;
    }

    function toStep(
        ConfigQuoteInput calldata cfg,
        ConfigPairInput calldata pair,
        bool reverse
    ) internal pure returns (SwapStep memory step) {
        address inToken = reverse ? cfg.tokenOut : cfg.tokenIn;
        address outToken = reverse ? cfg.tokenIn : cfg.tokenOut;

        step.kind = pair.kind;
        step.router = pair.router;
        step.pool = pair.pool;
        step.tokenIn = inToken;
        step.tokenOut = outToken;
        step.v4Fee = pair.v4Fee;
        step.v4TickSpacing = pair.v4TickSpacing;
        step.v4Hooks = pair.v4Hooks;

        if (pair.kind == 0 || pair.kind == 2) {
            address[] memory path = new address[](2);
            path[0] = inToken;
            path[1] = outToken;
            step.path = path;
        } else {
            step.path = new address[](0);
        }

        return step;
    }

    function invertStep(SwapStep memory s) internal pure returns (SwapStep memory inv) {
        inv.kind = s.kind;
        inv.router = s.router;
        inv.pool = s.pool;
        inv.tokenIn = s.tokenOut;
        inv.tokenOut = s.tokenIn;
        inv.v4Fee = s.v4Fee;
        inv.v4TickSpacing = s.v4TickSpacing;
        inv.v4Hooks = s.v4Hooks;

        if (s.path.length == 2) {
            address[] memory revPath = new address[](2);
            revPath[0] = s.path[1];
            revPath[1] = s.path[0];
            inv.path = revPath;
        } else {
            inv.path = new address[](0);
        }

        return inv;
    }
}

