// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

/* =========================================================
 * Store interface (route config)
 * ========================================================= */
interface ISwapStepsConfigStore {
    struct SwapStep {
        uint8 kind;

        // V2
        address router;
        address[] path; // must be length 0 or 2

        // V3/Algebra
        address pool;

        // common
        address tokenIn;
        address tokenOut;

        // V4 (Uniswap V4) — PoolKey components
        uint24  v4Fee;
        int24   v4TickSpacing;
        address v4Hooks;
    }

    function getConfig(bytes32 key) external view returns (SwapStep[] memory);
    function getAllKeys() external view returns (bytes32[] memory);
}

/* =========================================================
 * ArbExecutor interface (simulateSwaps always reverts Simulated)
 * ========================================================= */
interface IArbExecutor {
    struct SwapStep {
        uint8 kind;

        // V2
        address router;
        address[] path;

        // V3
        address pool;

        // common
        address tokenIn;
        address tokenOut;

        // runtime
        uint256 amountIn;
        uint256 amountOutMin;
        uint160 sqrtPriceLimitX96;
        uint256 deadline;
    }

    struct SwapLog {
        uint256 index;
        uint8 kind;
        address target;

        address tokenIn;
        address tokenOut;

        uint256 amountIn;
        uint256 amountOut;

        uint256 gasUsed;
    }

    struct ArbSummary {
        uint256 blockNumber;
        uint256 blockTimestamp;

        address profitToken;
        uint256 startBalance;
        uint256 endBalance;

        int256 profit;
        uint256 totalGasUsed;
        uint256 stepsCount;
    }

    error Simulated(ArbSummary summary, SwapLog[] logs);

    function simulateSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss
    ) external;
}

/* =========================================================
 * ArbQuoteRouter
 * ========================================================= */
contract ArbQuoteRouter is Ownable {
    ISwapStepsConfigStore private _store;
    IArbExecutor private _executor;

    event StoreUpdated(address indexed newStore);
    event ExecutorUpdated(address indexed newExecutor);

    error ZERO_ADDRESS();
    error STORE_NOT_SET();
    error EXECUTOR_NOT_SET();
    error EMPTY_CONFIG();
    error BAD_PATH_LEN(uint256 len);
    error NOT_SIMULATED_REVERT(bytes data);

    constructor(address initialOwner) Ownable(initialOwner) {}

    // =========================
    // setters (owner-only)
    // =========================
    function setStore(address newStore) external onlyOwner {
        if (newStore == address(0)) revert ZERO_ADDRESS();
        _store = ISwapStepsConfigStore(newStore);
        emit StoreUpdated(newStore);
    }

    function setExecutor(address newExecutor) external onlyOwner {
        if (newExecutor == address(0)) revert ZERO_ADDRESS();
        _executor = IArbExecutor(newExecutor);
        emit ExecutorUpdated(newExecutor);
    }

    // =========================
    // getters (addresses)
    // =========================
    function getStore() external view returns (address) {
        return address(_store);
    }

    function getExecutor() external view returns (address) {
        return address(_executor);
    }

    // =========================================================
    // Quote ONE key: returns last amountOut from logs
    // =========================================================
    function quoteByKeyExactIn(
        bytes32 key,
        uint256 amountIn,
        address profitToken,
        bool revertIfLoss
    ) external returns (uint256 amountOutLast) {
        if (address(_store) == address(0)) revert STORE_NOT_SET();
        if (address(_executor) == address(0)) revert EXECUTOR_NOT_SET();

        IArbExecutor.SwapStep[] memory steps = _buildSteps(key, amountIn);

        try _executor.simulateSwaps(steps, profitToken, revertIfLoss) {
            // simulateSwaps должен always revert Simulated(...)
            revert NOT_SIMULATED_REVERT("");
        } catch (bytes memory data) {
            amountOutLast = _decodeLastAmountOutFromSimulated(data);
        }
    }

    // =========================================================
    // Quote ALL keys: returns last amountOut per key
    // =========================================================
    function quoteAllKeysExactIn(
        uint256 amountIn,
        address profitToken,
        bool revertIfLoss
    ) external returns (bytes32[] memory keys, uint256[] memory amountOutLastList) {
        if (address(_store) == address(0)) revert STORE_NOT_SET();
        if (address(_executor) == address(0)) revert EXECUTOR_NOT_SET();

        keys = _store.getAllKeys();
        uint256 n = keys.length;

        amountOutLastList = new uint256[](n);

        for (uint256 k = 0; k < n; k++) {
            IArbExecutor.SwapStep[] memory steps = _buildSteps(keys[k], amountIn);

            try _executor.simulateSwaps(steps, profitToken, revertIfLoss) {
                revert NOT_SIMULATED_REVERT("");
            } catch (bytes memory data) {
                amountOutLastList[k] = _decodeLastAmountOutFromSimulated(data);
            }
        }
    }

    // =========================================================
    // Build runtime steps for ArbExecutor
    // =========================================================
    function _buildSteps(bytes32 key, uint256 amountIn)
    internal
    view
    returns (IArbExecutor.SwapStep[] memory steps)
    {
        ISwapStepsConfigStore.SwapStep[] memory cfg = _store.getConfig(key);
        uint256 n = cfg.length;
        if (n == 0) revert EMPTY_CONFIG();

        steps = new IArbExecutor.SwapStep[](n);

        for (uint256 i = 0; i < n; i++) {
            steps[i].kind = cfg[i].kind;
            steps[i].router = cfg[i].router;
            steps[i].pool = cfg[i].pool;
            steps[i].tokenIn = cfg[i].tokenIn;
            steps[i].tokenOut = cfg[i].tokenOut;

            // ✅ deep-copy path (0 or 2)
            uint256 pl = cfg[i].path.length;
            if (pl == 2) {
                address[] memory p = new address[](2);
                p[0] = cfg[i].path[0];
                p[1] = cfg[i].path[1];
                steps[i].path = p;
            } else if (pl == 0) {
                steps;
            } else {
                revert BAD_PATH_LEN(pl);
            }

            // runtime fields
            steps[i].amountIn = (i == 0) ? amountIn : 0;
            steps[i].amountOutMin = 0;
            steps[i].sqrtPriceLimitX96 = 0;
            steps[i].deadline = 0;
        }
    }

    // =========================================================
    // Decode revert data of Simulated(summary, logs)
    // Return last logs[].amountOut
    // =========================================================
    function _decodeLastAmountOutFromSimulated(bytes memory data)
    internal
    pure
    returns (uint256 lastAmountOut)
    {
        if (data.length < 4) revert NOT_SIMULATED_REVERT(data);

        bytes4 sel;
        assembly {
            sel := mload(add(data, 32))
        }

        if (sel != IArbExecutor.Simulated.selector) {
            revert NOT_SIMULATED_REVERT(data);
        }

        bytes memory payload = _slice(data, 4, data.length - 4);
        (, IArbExecutor.SwapLog[] memory logs) =
                            abi.decode(payload, (IArbExecutor.ArbSummary, IArbExecutor.SwapLog[]));

        if (logs.length == 0) return 0;
        return logs[logs.length - 1].amountOut;
    }

    function _slice(bytes memory data, uint256 start, uint256 len)
    internal
    pure
    returns (bytes memory out)
    {
        out = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            out[i] = data[start + i];
        }
    }
}

