pragma solidity ^0.8.20;

import "./SwapStepsConfigStore.sol";
import "./ArbExecutor.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/* =========================================================
 * Interface for ArbExecutor.simulateSwaps (always reverts)
 * ========================================================= */
interface IArbExecutorSim {
    struct SwapStep {
        uint8 kind;
        address router;
        address[] path;
        address pool;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 amountOutMin;
        uint160 sqrtPriceLimitX96;
        uint256 deadline;
    }

    struct SwapLog {
        uint256 index;
        uint8 kind;
        address target;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 amountOut;
        uint256 gasUsed;
    }

    struct ArbSummary {
        uint256 blockNumber;
        uint256 blockTimestamp;
        address profitToken;
        uint256 startBalance;
        uint256 endBalance;
        int256 profit;
        uint256 totalGasUsed;
        uint256 stepsCount;
    }

    error Simulated(ArbSummary summary, SwapLog[] logs);

    function simulateSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss
    ) external;
}

contract SwapStepsConfigReader is Ownable {
    SwapStepsConfigStore public configStore;
    IArbExecutorSim public executor;

    error ZERO_ADDRESS();

    // =========================================================
    // Structs — buildExecutorSteps
    // =========================================================

    struct StepGroup {
        address tokenIn;
        address tokenOut;
        ArbExecutor.SwapStep[] steps;
    }

    struct GroupedBuildResult {
        StepGroup[] groups;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    // =========================================================
    // Structs — findArb
    // =========================================================

    /// @notice Result of sell-back simulation for one pool in a group.
    struct SellQuote {
        uint256 sellPoolIndex;   // index within the group
        int256  profit;          // finalWETH - amountIn (negative = loss)
        uint256 buyAmountOut;    // amountOut of the buy step
        uint256 sellAmountOut;   // amountOut of the sell step (= final WETH)
        uint256 gasUsed;         // total gas of 2-step simulation
        bool    success;         // false if simulation reverted unexpectedly
    }

    /// @notice Arb analysis for one (tokenIn, tokenOut) group.
    struct GroupArbResult {
        address tokenIn;
        address tokenOut;
        uint256 poolCount;        // total pools in this group
        uint256 bestBuyIndex;     // index of pool with best buy price within group
        uint256 bestBuyAmountOut; // amountOut of best buy pool
        SellQuote[] sells;        // one entry per pool (sell-back via each pool)
        bool    hasProfitable;    // true if at least one sell is profitable
    }

    /// @notice Full arb scan result.
    struct ArbScanResult {
        GroupArbResult[] groups;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    // =========================================================
    // Constructor
    // =========================================================

    constructor(address initialOwner) Ownable(initialOwner) {}

    // =========================================================
    // Setters (onlyOwner)
    // =========================================================

    function setConfigStore(address _configStore) external onlyOwner {
        if (_configStore == address(0)) revert ZERO_ADDRESS();
        configStore = SwapStepsConfigStore(_configStore);
    }

    function setExecutor(address _executor) external onlyOwner {
        if (_executor == address(0)) revert ZERO_ADDRESS();
        executor = IArbExecutorSim(_executor);
    }

    // =========================================================
    // getConfig (unchanged)
    // =========================================================

    function getConfig(bytes32 key)
        external
        view
        returns (SwapStepsConfigStore.SwapStep[] memory)
    {
        return configStore.getConfig(key);
    }

    // =========================================================
    // buildExecutorSteps (unchanged)
    // =========================================================

    function buildExecutorSteps(
        bytes32 key,
        uint256 amountIn
    ) external view returns (GroupedBuildResult memory result) {
        uint256 gasStart = gasleft();

        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result.groups = _groupSteps(raw, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Same as buildExecutorSteps but accepts raw steps directly (no store lookup).
    function buildExecutorStepsDirect(
        SwapStepsConfigStore.SwapStep[] calldata rawSteps,
        uint256 amountIn
    ) external view returns (GroupedBuildResult memory result) {
        uint256 gasStart = gasleft();

        result.groups = _groupSteps(rawSteps, amountIn);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // findArb — main entry point
    // =========================================================

    /// @notice Analyse all pools under `key` for arbitrage opportunities.
    ///         Must be called via staticCall (simulateSwaps mutates state then reverts).
    ///
    /// Algorithm:
    ///   1. Get raw configs from store by key
    ///   2. Build one SwapStep per pool with amountIn, simulate each individually
    ///   3. Group results by (tokenIn,tokenOut), find best buy price per group
    ///   4. For each group: simulate 2-step arb (buy in best pool → sell-back in each pool)
    ///   5. Return grouped report with profit info
    function findArb(
        bytes32 key,
        uint256 amountIn,
        address profitToken
    ) external returns (ArbScanResult memory result) {
        uint256 gasStart = gasleft();

        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result = _findArbInternal(_toSimSteps(raw, amountIn), profitToken);
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Same as findArb but accepts raw steps directly (no store lookup).
    function findArbDirect(
        SwapStepsConfigStore.SwapStep[] calldata rawSteps,
        uint256 amountIn,
        address profitToken
    ) external returns (ArbScanResult memory result) {
        uint256 gasStart = gasleft();

        result = _findArbInternal(_toSimSteps(rawSteps, amountIn), profitToken);
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // Fast path: 2-call flow for bots (1 RPC each)
    // =========================================================

    /// @notice Результат buy-квоты для одного пула.
    struct BuyQuote {
        uint256 index;       // index in raw config array
        address tokenIn;
        address tokenOut;
        uint256 amountOut;   // 0 if failed
        bool    success;
    }

    /// @notice Результат quoteBuys.
    struct BuyQuotesResult {
        BuyQuote[] quotes;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    /// @notice Этап 1: симулирует buy для каждого пула по ключу.
    ///         Один staticCall → все buy-квоты.
    ///         Бот затем off-chain группирует и находит bestBuyIndex.
    function quoteBuys(
        bytes32 key,
        uint256 amountIn
    ) external returns (BuyQuotesResult memory result) {
        uint256 gasStart = gasleft();

        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        result = _buildBuyQuotesResult(_toSimSteps(raw, amountIn));
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Same as quoteBuys but accepts raw steps directly (no store lookup).
    function quoteBuysDirect(
        SwapStepsConfigStore.SwapStep[] calldata rawSteps,
        uint256 amountIn
    ) external returns (BuyQuotesResult memory result) {
        uint256 gasStart = gasleft();

        result = _buildBuyQuotesResult(_toSimSteps(rawSteps, amountIn));
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Пара индексов для arb-симуляции.
    struct ArbPairInput {
        uint256 buyIndex;    // index of buy pool in raw config
        uint256 sellIndex;   // index of sell pool (will be inverted)
    }

    /// @notice Результат arb-симуляции одной пары.
    struct ArbPairResult {
        uint256 buyIndex;
        uint256 sellIndex;
        int256  profit;
        uint256 buyAmountOut;
        uint256 sellAmountOut;
        uint256 gasUsed;
        bool    success;
    }

    /// @notice Результат scanArbPairs.
    struct ArbPairsResult {
        ArbPairResult[] results;
        uint256 blockNumber;
        uint256 gasUsed;
    }

    /// @notice Этап 2: бот передаёт список пар (buyIdx, sellIdx),
    ///         контракт симулирует 2-step arb для каждой.
    ///         Один staticCall → все arb-результаты.
    function scanArbPairs(
        bytes32 key,
        uint256 amountIn,
        address profitToken,
        ArbPairInput[] calldata pairs
    ) external returns (ArbPairsResult memory result) {
        uint256 gasStart = gasleft();

        SwapStepsConfigStore.SwapStep[] memory raw = configStore.getConfig(key);
        IArbExecutorSim.SwapStep[] memory allSteps = _toSimSteps(raw, amountIn);

        result.results = _scanArbPairsInternal(allSteps, pairs, profitToken);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    /// @notice Same as scanArbPairs but accepts raw steps directly (no store lookup).
    function scanArbPairsDirect(
        SwapStepsConfigStore.SwapStep[] calldata rawSteps,
        uint256 amountIn,
        address profitToken,
        ArbPairInput[] calldata pairs
    ) external returns (ArbPairsResult memory result) {
        uint256 gasStart = gasleft();

        IArbExecutorSim.SwapStep[] memory allSteps = _toSimSteps(rawSteps, amountIn);

        result.results = _scanArbPairsInternal(allSteps, pairs, profitToken);
        result.blockNumber = block.number;
        result.gasUsed = gasStart - gasleft();
    }

    // =========================================================
    // Internal — simulation helpers
    // =========================================================

    /// @dev Call executor.simulateSwaps, decode Simulated revert.
    function _simulate(
        IArbExecutorSim.SwapStep[] memory steps,
        address profitToken
    ) internal returns (bool success, uint256 lastAmountOut, uint256 totalGas) {
        try executor.simulateSwaps(steps, profitToken, false) {
            return (false, 0, 0);
        } catch (bytes memory data) {
            return _decodeSimulated(data);
        }
    }

    /// @dev Simulate a 2-step arb: buy in bestPool, sell-back in sellPool.
    function _simulateArb(
        IArbExecutorSim.SwapStep memory buyStep,
        IArbExecutorSim.SwapStep memory sellStep,
        address profitToken
    ) internal returns (bool success, int256 profit, uint256 buyAmtOut, uint256 sellAmtOut, uint256 gasUsed) {
        IArbExecutorSim.SwapStep[] memory pair = new IArbExecutorSim.SwapStep[](2);
        pair[0] = buyStep;
        pair[1] = sellStep;  // amountIn=0 → auto from prevOut

        try executor.simulateSwaps(pair, profitToken, false) {
            return (false, int256(0), 0, 0, 0);
        } catch (bytes memory data) {
            if (data.length < 4) return (false, int256(0), 0, 0, 0);

            bytes4 sel;
            assembly { sel := mload(add(data, 32)) }
            if (sel != IArbExecutorSim.Simulated.selector) return (false, int256(0), 0, 0, 0);

            bytes memory payload = _slice(data, 4, data.length - 4);
            (IArbExecutorSim.ArbSummary memory summary, IArbExecutorSim.SwapLog[] memory logs) =
                abi.decode(payload, (IArbExecutorSim.ArbSummary, IArbExecutorSim.SwapLog[]));

            if (logs.length < 2) return (false, int256(0), 0, 0, 0);

            return (
                true,
                summary.profit,
                logs[0].amountOut,
                logs[1].amountOut,
                summary.totalGasUsed
            );
        }
    }

    /// @dev Decode Simulated revert data → (success, lastAmountOut, totalGasUsed).
    function _decodeSimulated(bytes memory data)
        internal pure returns (bool, uint256, uint256)
    {
        if (data.length < 4) return (false, 0, 0);

        bytes4 sel;
        assembly { sel := mload(add(data, 32)) }
        if (sel != IArbExecutorSim.Simulated.selector) return (false, 0, 0);

        bytes memory payload = _slice(data, 4, data.length - 4);
        (IArbExecutorSim.ArbSummary memory summary, IArbExecutorSim.SwapLog[] memory logs) =
            abi.decode(payload, (IArbExecutorSim.ArbSummary, IArbExecutorSim.SwapLog[]));

        if (logs.length == 0) return (true, 0, summary.totalGasUsed);
        return (true, logs[logs.length - 1].amountOut, summary.totalGasUsed);
    }

    // =========================================================
    // Internal — arb report builder
    // =========================================================

    function _buildArbReport(
        IArbExecutorSim.SwapStep[] memory allSteps,
        uint256[] memory amountsOut,
        bool[] memory buyOk,
        address profitToken
    ) internal returns (GroupArbResult[] memory groups) {
        Phase3Ctx memory ctx;
        (groups, ctx) = _groupAndFindBest(allSteps, amountsOut, buyOk);
        ctx.profitToken = profitToken;
        _simulateAndDistribute(groups, allSteps, ctx);
    }

    /// @dev Phase 1+2: group by (tokenIn, tokenOut), find best buy per group, collect member indices.
    function _groupAndFindBest(
        IArbExecutorSim.SwapStep[] memory allSteps,
        uint256[] memory amountsOut,
        bool[] memory buyOk
    ) internal pure returns (GroupArbResult[] memory groups, Phase3Ctx memory ctx) {
        uint256 n = allSteps.length;

        address[] memory uIn  = new address[](n);
        address[] memory uOut = new address[](n);
        ctx.bestIdx    = new uint256[](n);
        ctx.bestAmtOut = new uint256[](n);
        ctx.counts     = new uint256[](n);
        uint256 gc = 0;

        for (uint256 i = 0; i < n; i++) {
            bool found = false;
            for (uint256 g = 0; g < gc; g++) {
                if (uIn[g] == allSteps[i].tokenIn && uOut[g] == allSteps[i].tokenOut) {
                    ctx.counts[g]++;
                    if (buyOk[i] && amountsOut[i] > ctx.bestAmtOut[g]) {
                        ctx.bestAmtOut[g] = amountsOut[i];
                        ctx.bestIdx[g] = i;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) {
                uIn[gc]  = allSteps[i].tokenIn;
                uOut[gc] = allSteps[i].tokenOut;
                ctx.counts[gc] = 1;
                ctx.bestIdx[gc] = i;
                ctx.bestAmtOut[gc] = buyOk[i] ? amountsOut[i] : 0;
                gc++;
            }
        }
        ctx.gc = gc;

        // Phase 2: allocate groups & collect member indices
        groups = new GroupArbResult[](gc);
        uint256[] memory cursor = new uint256[](gc);
        ctx.memberIdx = new uint256[][](gc);

        for (uint256 g = 0; g < gc; g++) {
            groups[g].tokenIn  = uIn[g];
            groups[g].tokenOut = uOut[g];
            groups[g].poolCount = ctx.counts[g];
            groups[g].bestBuyAmountOut = ctx.bestAmtOut[g];
            groups[g].sells = new SellQuote[](ctx.counts[g]);
            ctx.memberIdx[g] = new uint256[](ctx.counts[g]);
        }

        for (uint256 i = 0; i < n; i++) {
            for (uint256 g = 0; g < gc; g++) {
                if (uIn[g] == allSteps[i].tokenIn && uOut[g] == allSteps[i].tokenOut) {
                    ctx.memberIdx[g][cursor[g]] = i;
                    cursor[g]++;
                    break;
                }
            }
        }
    }

    /// @dev Phase 3 context, packed to avoid stack-too-deep.
    struct Phase3Ctx {
        uint256[][] memberIdx;
        uint256[] bestIdx;
        uint256[] bestAmtOut;
        uint256[] counts;
        uint256 gc;
        address profitToken;
    }

    /// @dev Phase 3: find bestBuyIndex, build ArbPairInput[], simulate, distribute results.
    ///      Extracted to avoid stack-too-deep in _buildArbReport.
    function _simulateAndDistribute(
        GroupArbResult[] memory groups,
        IArbExecutorSim.SwapStep[] memory allSteps,
        Phase3Ctx memory ctx
    ) internal {
        // Count total arb pairs & set bestBuyIndex
        uint256 totalPairs = 0;
        for (uint256 g = 0; g < ctx.gc; g++) {
            uint256 localBest = 0;
            for (uint256 j = 0; j < ctx.counts[g]; j++) {
                if (ctx.memberIdx[g][j] == ctx.bestIdx[g]) {
                    localBest = j;
                    break;
                }
            }
            groups[g].bestBuyIndex = localBest;
            if (ctx.bestAmtOut[g] > 0) totalPairs += ctx.counts[g];
        }

        // Build flat ArbPairInput array + mapping back to group/slot
        ArbPairInput[] memory pairs = new ArbPairInput[](totalPairs);
        uint256[] memory pairGroup = new uint256[](totalPairs);
        uint256[] memory pairSlot  = new uint256[](totalPairs);
        uint256 pi = 0;

        for (uint256 g = 0; g < ctx.gc; g++) {
            if (ctx.bestAmtOut[g] == 0) {
                for (uint256 j = 0; j < ctx.counts[g]; j++) {
                    groups[g].sells[j] = SellQuote(j, int256(0), 0, 0, 0, false);
                }
                continue;
            }
            for (uint256 j = 0; j < ctx.counts[g]; j++) {
                pairs[pi] = ArbPairInput(ctx.bestIdx[g], ctx.memberIdx[g][j]);
                pairGroup[pi] = g;
                pairSlot[pi]  = j;
                pi++;
            }
        }

        // Simulate all via shared internal
        ArbPairResult[] memory arbResults = _scanArbPairsInternal(allSteps, pairs, ctx.profitToken);

        // Distribute results back into groups
        for (uint256 i = 0; i < totalPairs; i++) {
            ArbPairResult memory r = arbResults[i];
            groups[pairGroup[i]].sells[pairSlot[i]] = SellQuote(
                pairSlot[i], r.profit, r.buyAmountOut, r.sellAmountOut, r.gasUsed, r.success
            );
            if (r.success && r.profit > 0) {
                groups[pairGroup[i]].hasProfitable = true;
            }
        }
    }

    // =========================================================
    // Internal — step conversion helpers
    // =========================================================

    /// @dev Convert raw store steps to simulator-ready steps with amountIn.
    function _toSimSteps(
        SwapStepsConfigStore.SwapStep[] memory raw,
        uint256 amountIn
    ) internal pure returns (IArbExecutorSim.SwapStep[] memory steps) {
        uint256 n = raw.length;
        steps = new IArbExecutorSim.SwapStep[](n);

        for (uint256 i = 0; i < n; i++) {
            steps[i] = IArbExecutorSim.SwapStep({
                kind:              raw[i].kind,
                router:            raw[i].router,
                path:              raw[i].path,
                pool:              raw[i].pool,
                tokenIn:           raw[i].tokenIn,
                tokenOut:          raw[i].tokenOut,
                amountIn:          amountIn,
                amountOutMin:      0,
                sqrtPriceLimitX96: 0,
                deadline:          0
            });
        }
    }

    /// @dev Invert a step: swap tokenIn↔tokenOut, reverse path, amountIn=0 (auto from prev).
    function _invertStep(
        IArbExecutorSim.SwapStep memory s
    ) internal pure returns (IArbExecutorSim.SwapStep memory inv) {
        inv.kind              = s.kind;
        inv.router            = s.router;
        inv.pool              = s.pool;
        inv.tokenIn           = s.tokenOut;  // reversed
        inv.tokenOut          = s.tokenIn;   // reversed
        inv.amountIn          = 0;           // auto from previous step output
        inv.amountOutMin      = 0;
        inv.sqrtPriceLimitX96 = 0;
        inv.deadline          = 0;

        // Reverse path for V2
        if (s.path.length == 2) {
            address[] memory revPath = new address[](2);
            revPath[0] = s.path[1];
            revPath[1] = s.path[0];
            inv.path = revPath;
        } else {
            inv.path = new address[](0);
        }
    }

    // =========================================================
    // Internal — groupSteps (for buildExecutorSteps, unchanged)
    // =========================================================

    function _groupSteps(
        SwapStepsConfigStore.SwapStep[] memory raw,
        uint256 amountIn
    ) internal pure returns (StepGroup[] memory groups) {
        uint256 n = raw.length;
        if (n == 0) {
            groups = new StepGroup[](0);
            return groups;
        }

        address[] memory uTokenIn  = new address[](n);
        address[] memory uTokenOut = new address[](n);
        uint256[] memory counts    = new uint256[](n);
        uint256 groupCount = 0;

        for (uint256 i = 0; i < n; i++) {
            bool found = false;
            for (uint256 g = 0; g < groupCount; g++) {
                if (uTokenIn[g] == raw[i].tokenIn && uTokenOut[g] == raw[i].tokenOut) {
                    counts[g]++;
                    found = true;
                    break;
                }
            }
            if (!found) {
                uTokenIn[groupCount]  = raw[i].tokenIn;
                uTokenOut[groupCount] = raw[i].tokenOut;
                counts[groupCount]    = 1;
                groupCount++;
            }
        }

        groups = new StepGroup[](groupCount);
        for (uint256 g = 0; g < groupCount; g++) {
            groups[g].tokenIn  = uTokenIn[g];
            groups[g].tokenOut = uTokenOut[g];
            groups[g].steps    = new ArbExecutor.SwapStep[](counts[g]);
            counts[g] = 0;
        }

        for (uint256 i = 0; i < n; i++) {
            for (uint256 g = 0; g < groupCount; g++) {
                if (uTokenIn[g] == raw[i].tokenIn && uTokenOut[g] == raw[i].tokenOut) {
                    uint256 idx = counts[g]++;
                    groups[g].steps[idx] = ArbExecutor.SwapStep({
                        kind:              ArbExecutor.SwapKind(raw[i].kind),
                        router:            raw[i].router,
                        path:              raw[i].path,
                        pool:              raw[i].pool,
                        tokenIn:           raw[i].tokenIn,
                        tokenOut:          raw[i].tokenOut,
                        amountIn:          amountIn,
                        amountOutMin:      0,
                        sqrtPriceLimitX96: 0,
                        deadline:          0
                    });
                    break;
                }
            }
        }
    }

    // =========================================================
    // Internal — bytes utils
    // =========================================================

    function _slice(bytes memory data, uint256 start, uint256 len)
        internal pure returns (bytes memory out)
    {
        out = new bytes(len);
        for (uint256 i = 0; i < len; i++) {
            out[i] = data[start + i];
        }
    }

    // =========================================================
    // Internal — shared quoteBuys logic
    // =========================================================

    /// @dev Simulate each pool in allSteps, return arrays of amountsOut and success flags.
    function _quoteBuysInternal(
        IArbExecutorSim.SwapStep[] memory allSteps
    ) internal returns (uint256[] memory amountsOut, bool[] memory buyOk) {
        uint256 n = allSteps.length;

        amountsOut = new uint256[](n);
        buyOk = new bool[](n);
        for (uint256 i = 0; i < n; i++) {
            IArbExecutorSim.SwapStep[] memory single = new IArbExecutorSim.SwapStep[](1);
            single[0] = allSteps[i];
            // Use tokenOut as profitToken for buy-only simulation
            address buyProfitToken = allSteps[i].tokenOut;
            (bool ok, uint256 amtOut,) = _simulate(single, buyProfitToken);
            amountsOut[i] = amtOut;
            buyOk[i] = ok;
        }
    }

    /// @dev Shared: simulate buy quotes and build BuyQuotesResult.
    function _buildBuyQuotesResult(
        IArbExecutorSim.SwapStep[] memory allSteps
    ) internal returns (BuyQuotesResult memory result) {
        (uint256[] memory amountsOut, bool[] memory buyOk) = _quoteBuysInternal(allSteps);

        uint256 n = allSteps.length;
        result.quotes = new BuyQuote[](n);
        for (uint256 i = 0; i < n; i++) {
            result.quotes[i] = BuyQuote({
                index: i,
                tokenIn: allSteps[i].tokenIn,
                tokenOut: allSteps[i].tokenOut,
                amountOut: amountsOut[i],
                success: buyOk[i]
            });
        }
        result.blockNumber = block.number;
    }

    /// @dev Shared: full arb scan from allSteps.
    function _findArbInternal(
        IArbExecutorSim.SwapStep[] memory allSteps,
        address profitToken
    ) internal returns (ArbScanResult memory result) {
        (uint256[] memory amountsOut, bool[] memory buyOk) = _quoteBuysInternal(allSteps);
        result.groups = _buildArbReport(allSteps, amountsOut, buyOk, profitToken);
        result.blockNumber = block.number;
    }

    /// @notice Этап 2: бот передаёт список пар (buyIdx, sellIdx),
    ///         контракт симулирует 2-step arb для каждой.
    ///         Один staticCall → все arb-результаты.
    function _scanArbPairsInternal(
        IArbExecutorSim.SwapStep[] memory allSteps,
        ArbPairInput[] memory pairs,
        address profitToken
    ) internal returns (ArbPairResult[] memory results) {
        uint256 pLen = pairs.length;
        results = new ArbPairResult[](pLen);

        for (uint256 i = 0; i < pLen; i++) {
            IArbExecutorSim.SwapStep memory buyStep = allSteps[pairs[i].buyIndex];
            IArbExecutorSim.SwapStep memory sellStep = _invertStep(allSteps[pairs[i].sellIndex]);

            (bool ok, int256 pft, uint256 buyAmtO, uint256 sellAmtO, uint256 gas) =
                _simulateArb(buyStep, sellStep, profitToken);

            results[i] = ArbPairResult({
                buyIndex: pairs[i].buyIndex,
                sellIndex: pairs[i].sellIndex,
                profit: pft,
                buyAmountOut: buyAmtO,
                sellAmountOut: sellAmtO,
                gasUsed: gas,
                success: ok
            });
        }
    }
}

