pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

contract SwapStepsConfigStore is Ownable {
    // ============ Errors ============
    error BAD_PATH_LEN();
    error KEY_NOT_FOUND();

    // ============ Data ============
    struct SwapStep {
        uint8 kind;

        // V2
        address router;
        address[] path;

        // V3 / Algebra
        address pool;

        // common
        address tokenIn;
        address tokenOut;

        // V4 (Uniswap V4) — PoolKey components
        uint24  v4Fee;
        int24   v4TickSpacing;
        address v4Hooks;
    }

    mapping(bytes32 => SwapStep[]) private _configs;

    bytes32[] private _keys;
    mapping(bytes32 => uint256) private _keyIndex; // index + 1

    event ConfigSet(bytes32 indexed key, uint256 stepsCount);
    event ConfigDeleted(bytes32 indexed key);

    constructor(address initialOwner) Ownable(initialOwner) {}

    // =========================
    // OWNER-ONLY MUTATIONS
    // =========================

    function setConfig(bytes32 key, SwapStep[] calldata steps) external onlyOwner {
        // add key if new
        if (_keyIndex[key] == 0) {
            _keys.push(key);
            _keyIndex[key] = _keys.length; // index + 1
        }

        delete _configs[key];

        uint256 n = steps.length;
        for (uint256 i = 0; i < n; i++) {
            _configs[key].push();
            SwapStep storage s = _configs[key][i];

            s.kind = steps[i].kind;

            s.router = steps[i].router;
            s.pool = steps[i].pool;

            s.tokenIn = steps[i].tokenIn;
            s.tokenOut = steps[i].tokenOut;

            // V4 PoolKey fields
            s.v4Fee = steps[i].v4Fee;
            s.v4TickSpacing = steps[i].v4TickSpacing;
            s.v4Hooks = steps[i].v4Hooks;

            uint256 pl = steps[i].path.length;
            if (pl == 2) {
                s.path.push(steps[i].path[0]);
                s.path.push(steps[i].path[1]);
            } else if (pl != 0) {
                revert BAD_PATH_LEN();
            }
        }

        emit ConfigSet(key, n);
    }

    function deleteConfig(bytes32 key) external onlyOwner {
        uint256 indexPlusOne = _keyIndex[key];
        if (indexPlusOne == 0) revert KEY_NOT_FOUND();

        delete _configs[key];

        // swap & pop key
        uint256 index = indexPlusOne - 1;
        uint256 lastIndex = _keys.length - 1;

        if (index != lastIndex) {
            bytes32 lastKey = _keys[lastIndex];
            _keys[index] = lastKey;
            _keyIndex[lastKey] = index + 1;
        }

        _keys.pop();
        delete _keyIndex[key];

        emit ConfigDeleted(key);
    }

    // =========================
    // GETTERS
    // =========================

    function getConfig(bytes32 key) external view returns (SwapStep[] memory) {
        return _configs[key];
    }

    function getAllKeys() external view returns (bytes32[] memory) {
        return _keys;
    }

    function getKeysCount() external view returns (uint256) {
        return _keys.length;
    }
}

