// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import "./ArbErrors.sol";

interface IUniswapV2RouterLike {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

library V2SwapLib {
    using SafeERC20 for IERC20;

    function swapExactIn(
        address router,
        address tokenIn,
        address tokenOut,
        address[] calldata pathCalldata,   // может быть пустой/короткой => сделаем default
        uint256 amountIn,
        uint256 amountOutMin,
        uint256 deadline
    ) internal returns (uint256 amountOut, uint256 spent) {
        if (router == address(0)) revert ArbErrors.ROUTER_ZERO();

        address[] memory path = (pathCalldata.length >= 2)
            ? _copyPath(pathCalldata)
            : _defaultPath(tokenIn, tokenOut);

        if (path.length < 2) revert ArbErrors.PATH_TOO_SHORT();
        if (path[0] != tokenIn || path[path.length - 1] != tokenOut) revert ArbErrors.TOKEN_NOT_IN_POOL();

        _ensureAllowance(tokenIn, router, amountIn);

        uint[] memory amounts = IUniswapV2RouterLike(router).swapExactTokensForTokens(
            amountIn,
            amountOutMin, // can be 0
            path,
            address(this),
            deadline
        );

        spent = amounts[0];
        amountOut = amounts[amounts.length - 1];
    }

    // -------- utils --------

    function _defaultPath(address tokenIn, address tokenOut) private pure returns (address[] memory path) {
        path = new address[](2);
        path[0] = tokenIn;
        path[1] = tokenOut;
    }

    function _copyPath(address[] calldata p) private pure returns (address[] memory out) {
        out = new address[](p.length);
        for (uint256 i = 0; i < p.length; i++) out[i] = p[i];
    }

    function _ensureAllowance(address token, address spender, uint256 needed) private {
        IERC20 erc = IERC20(token);
        uint256 allowance = erc.allowance(address(this), spender);
        if (allowance < needed) {
            erc.forceApprove(spender, type(uint256).max);
        }
    }
}

